mapper.select:
SELECT COALESCE(MAX(seq), 0) + 1
FROM chat_message
WHERE session_id = #{sessionId}

mapper.insert:
INSERT INTO chat_message (
    session_id, seq, direction, node_id, option_id, content, payload, latency_ms
)
VALUES (
    #{sessionId}, #{seq}, #{direction}, #{nodeId}, #{optionId}, #{content},
    CAST(#{payload} AS jsonb), #{latencyMs}
)
